"""Structured large-core validation: two-pass marginals vs evidence clamping."""
import json, random, sys, time
sys.path.insert(0, '/workspace/tmp')
sys.path.insert(0, '/workspace/submission')
import ref, main as M
from bigtest import forward_Z, Z_evidence


def gen_struct(seed):
    rnd = random.Random(seed)
    style = rnd.randint(0, 3)
    rib = []
    if style == 0:
        # sliding windows on a chain (width ~2 scope graph)
        nn = rnd.randint(4, 40)
        chain = list(range(10, 10 + nn * 7, 7))
        w = rnd.randint(2, min(10, nn))
        for s in range(0, max(1, nn - w + 1)):
            seg = chain[s:s + w]
            if rnd.random() < 0.5:
                seg = seg[::-1]
            rib.append({'path': list(seg), 'count': rnd.randint(1, 5)})
    elif style == 1:
        # several disjoint chains -> independent components
        comps = rnd.randint(1, 4)
        for c in range(comps):
            nn = rnd.randint(2, 12)
            chain = [1000 * c + 3 * i for i in range(nn)]
            w = rnd.randint(2, min(6, nn))
            for s in range(0, max(1, nn - w + 1)):
                seg = chain[s:s + w]
                if rnd.random() < 0.5:
                    seg = seg[::-1]
                rib.append({'path': list(seg), 'count': rnd.randint(1, 5)})
    elif style == 2:
        # caterpillar tree: spine plus leaves, paths along spine with detours
        nn = rnd.randint(4, 20)
        spine = [2000 + 5 * i for i in range(nn)]
        for s in range(0, max(1, nn - 3)):
            seg = spine[s:s + 4]
            if rnd.random() < 0.5:
                seg = seg[::-1]
            rib.append({'path': list(seg), 'count': rnd.randint(1, 4)})
        for _ in range(rnd.randint(0, 8)):
            i = rnd.randrange(max(1, nn - 1))
            leaf = 4000 + rnd.randrange(500)
            seg = [spine[i], leaf, spine[i + 1]]
            if rnd.random() < 0.5:
                seg = seg[::-1]
            rib.append({'path': seg, 'count': rnd.randint(1, 4)})
    else:
        # random low-width: paths of length 3 over shuffled nodes
        nn = rnd.randint(4, 16)
        nodes = list(range(5000, 5000 + nn * 3))
        for _ in range(rnd.randint(3, 20)):
            p = rnd.sample(nodes, rnd.randint(2, 5))
            rib.append({'path': p, 'count': rnd.randint(1, 5)})
    agg = {}
    for rec in rib:
        p = ref.normalize(rec['path'], set())
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    if not agg:
        return None
    final, rounds = ref.ref_peel(agg)
    f_mine, r_mine = M.peel(list(agg.items()))
    if f_mine != final or r_mine != rounds:
        return ('PEEL', agg, (f_mine, r_mine), (final, rounds))
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    if not core or len(core) > 64:
        return None
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    order = ref.find_order(adj)
    if order is None:
        return None
    vi = {l: i for i, l in enumerate(order)}
    occs_m = M.collect_occurrences(final)
    factors = [M.build_factor(l, occs_m.get(l, []), vi) for l in order]
    n = len(order)
    Z, marg = M.infer(factors, n)
    if Z != forward_Z(factors, n):
        return ('Z', order, Z, forward_Z(factors, n))
    if Z == 0:
        return ('ZP', n, None, None)
    for i in range(n):
        for t in (0, 1, 2):
            ze = Z_evidence(factors, n, i, t)
            if ze != marg[i][t]:
                return ('MARG', n, (i, t, ze, marg[i][t]), None)
    return ('OK', n, len(final), len(agg))


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    fails = 0
    stats = {}
    zp = 0
    for seed in range(lo, hi):
        r = gen_struct(seed)
        if r is None:
            continue
        kind = r[0]
        if kind == 'OK':
            stats[r[1]] = stats.get(r[1], 0) + 1
        elif kind == 'ZP':
            zp += 1
        else:
            print('seed', seed, 'FAIL', r)
            fails += 1
            if fails > 3:
                break
    print('tested', sum(stats.values()) + zp, 'fails', fails,
          'zero-partition', zp)
    ks = sorted(stats)
    print('core size histogram (max %d):' % (ks[-1] if ks else 0),
          {k: stats[k] for k in ks[::max(1, len(ks) // 12)]})
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
